// Layer 3 impersonation model, behind SHOO_L3_MODEL=impersonation (off by default: then nothing here runs).
// Model v2 of shoo-impersonation-lab (two TF-IDF + logistic regression judges, two gradient-boosted combiners), the
// "claim" gate v3g and the domain-age rule from ai/test-layer3/v7-2026-11-16-impersonation-new-data/FP-ANALISIS.md.
// Pure and synchronous: no network, nothing stored or logged. The numbers live in impersonation-data.js, generated by
// shoo-impersonation-lab/export_js.py; this file rebuilds the model's inputs exactly as the lab did
// (test-layer3/v5-2026-11-13-compare-alief-l3/build-rows.mjs and the lab's train2.py) and runs the arithmetic.
import brands from "../../../../detector/data/brands.json" with { type: "json" };
import { SHARED_HOSTS } from "../../blocklist/allowlist.js";
import { isOfficialHost, USER_CONTENT } from "../official.js";
import { BLOB, INFO } from "./impersonation-data.js";

export const MODEL_SIGNAL_ID = "impersonation_model";
/** warn = popup + layer 4 may add to it (total 30..79), block = blocked without asking layer 4 (total >= 80). */
export const MODEL_WEIGHTS = Object.freeze({ warn: 40, block: 80 });
const YOUNG_DAYS = 30;

// ---- page facts (build-rows.mjs addressFacts / rowFromSnapshot) ------------------------------------------------
const BRAND_NAMES = brands.brands.map((b) => [...new Set([b.name, ...(b.names || []), ...(b.commonNames || [])].map((n) => n.toLowerCase()))]);
const CHEAP_TLDS = new Set((brands.cheapTlds || []).map((t) => t.replace(/^\./, "").toLowerCase()));
const URL_KEYWORDS = (brands.keywords || []).map((k) => String(k).toLowerCase());
const esc = (t) => t.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const BRAND_WORD = BRAND_NAMES.map((names) => new RegExp(`(^|[^a-z0-9])(${names.map(esc).join("|")})([^a-z0-9]|$)`, "i"));
const SECOND_LEVEL = /^(co|go|ac|or|web|sch|my|biz|net|com|org|gov|edu|mil|desa|ponpes)\.[a-z]{2}$/;

/** Registrable-ish site of a host (the lab's `site`, not the PSL). */
export function site(host) {
    const p = host.replace(/^www\./, "").split(".");
    return p.slice(SECOND_LEVEL.test(p.slice(-2).join(".")) ? -3 : -2).join(".");
}

function urlHost(url) {
    try {
        return new URL(url).hostname.toLowerCase();
    } catch {
        return "";
    }
}

const noBanner = (t) => (t || "").replace(/The Wayback Machine - \S+\s*/g, "");

function addressFacts(title, text, host, url) {
    const official = isOfficialHost(host);
    const count = (s) => BRAND_WORD.filter((re) => re.test(s)).length;
    const inTitle = count(title);
    const inText = count(text.slice(0, 6000));
    const pieces = host.split(/[.\-_0-9]+/).filter(Boolean);
    const inHost = BRAND_NAMES.some((names) => names.some((n) => (n.length >= 5 ? host.includes(n.replace(/\s+/g, "")) : pieces.includes(n))));
    let path = "";
    try {
        path = new URL(url).pathname;
    } catch {}
    const labels = host.split(".");
    const lowered = (host + path).toLowerCase();
    return {
        official,
        brandsInTitle: inTitle,
        brandsInText: inText,
        brandOffsite: !official && inTitle > 0,
        brandTextOffsite: !official && inText > 0,
        brandInHost: !official && inHost,
        cheapTld: CHEAP_TLDS.has(labels[labels.length - 1]),
        sharedHost: [...SHARED_HOSTS].some((h) => host === h || host.endsWith("." + h)),
        hostLen: host.length,
        hostDigits: (host.match(/[0-9]/g) || []).length,
        hostHyphens: (host.match(/-/g) || []).length,
        subdomains: Math.max(0, labels.length - site(host).split(".").length),
        pathLen: path.length,
        pathDepth: path.split("/").filter(Boolean).length,
        ipHost: /^[0-9.]+$/.test(host),
        punycode: host.includes("xn--"),
        urlKeywords: URL_KEYWORDS.filter((k) => lowered.includes(k)).length,
    };
}

/** The model's row for one (sanitised) snapshot: { host, url, title, text, feats }. */
export function pageRow(snapshot) {
    const url = snapshot.url || "";
    const host = urlHost(url);
    const forms = snapshot.forms || [];
    const fields = forms.flatMap((f) => f.fields || []);
    const title = noBanner(snapshot.title);
    const text = noBanner(snapshot.text);
    return {
        host,
        url,
        title,
        text,
        feats: {
            textLen: text.length,
            fields: fields.length,
            passwordField: fields.some((f) => f.type === "password"),
            forms: forms.length,
            imageAlts: (snapshot.imageAlts || []).length,
            formActionOffsite: forms.some((f) => /^https?:\/\//i.test(f.action || "") && site(urlHost(f.action)) !== site(host)),
            ...addressFacts(title, text, host, url),
        },
    };
}

// ---- popular top 1000 (lab popular.py): a host under a Tranco top-1000 domain counts as official -------------------
const TOP = new Set(INFO.popular_top1000);
const NOT_POPULAR = [...SHARED_HOSTS, ...USER_CONTENT];

export function isPopular(rawHost) {
    const host = (rawHost || "").toLowerCase().replace(/\.+$/, "");
    if (!host || host.length > 253) return false;
    if (NOT_POPULAR.some((s) => host === s || host.endsWith("." + s))) return false;
    if (host.endsWith(".medium.com") && host !== "www.medium.com") return false;
    const labels = host.split(".");
    for (let i = 0; i < labels.length - 1; i++) if (TOP.has(labels.slice(i).join("."))) return true;
    return false;
}

// ---- language group (lab train2.is_indonesian) ----------------------------------------------------------------
const ID_WORDS = new Set(
    "yang dan di untuk dengan dari ini itu pada adalah atau juga akan tidak kami anda daftar masuk situs terbaru hari lebih dalam ke oleh sebagai bisa dapat beranda resmi terpercaya hubungi promosi permainan bermain menang mudah".split(" "),
);
const FOREIGN = new Set(
    ("il la le lo gli della delle dei del per che non una sono con come più les des et est pour vous nous avec sur dans une " +
        "ve bir için ile olan daha veya en el los las que para por com não uma das dos the and of to is are for with this").split(" "),
);
const cp = (s, n) => (s.length <= n ? s : Array.from(s).slice(0, n).join("")); // first n code points (Python slicing)

export function isIndonesian(row) {
    const words = (row.title + " " + cp(row.text, 4000)).toLowerCase().match(/[a-zçğıöşüàèéìòù]+/g) || [];
    if (words.length < 15) return false;
    let id = 0;
    let foreign = 0;
    for (const w of words) {
        if (ID_WORDS.has(w)) id++;
        if (FOREIGN.has(w)) foreign++;
    }
    return id / words.length >= 0.04 && id > foreign;
}

// ---- tokenizers (sklearn TfidfVectorizer: lowercase, word 1-2, char_wb 3-5, char 2-4) --------------------------------
function wordTerms(doc) {
    const tokens = (doc.toLowerCase().match(/[\p{L}\p{N}_]+/gu) || []).filter((t) => t.length >= 2 && Array.from(t).length >= 2);
    const out = tokens.slice();
    for (let i = 0; i + 1 < tokens.length; i++) out.push(tokens[i] + " " + tokens[i + 1]);
    return out;
}

function charWbTerms(doc, lo, hi) {
    const out = [];
    for (const word of doc.toLowerCase().replace(/\s\s+/g, " ").split(/\s+/)) {
        if (!word) continue;
        const w = Array.from(" " + word + " ");
        for (let n = lo; n <= hi; n++) {
            let offset = 0;
            out.push(w.slice(offset, offset + n).join(""));
            while (offset + n < w.length) {
                offset += 1;
                out.push(w.slice(offset, offset + n).join(""));
            }
            if (offset === 0) break; // word shorter than n: sklearn stops here
        }
    }
    return out;
}

function charTerms(doc, lo, hi) {
    const t = Array.from(doc.toLowerCase().replace(/\s\s+/g, " "));
    const out = [];
    for (let n = lo; n <= hi; n++) for (let i = 0; i + n <= t.length; i++) out.push(t.slice(i, i + n).join(""));
    return out;
}

const wordsText = (row) => row.title + " \n " + cp(row.text, 6000);
const addressText = (row) => row.host + " " + cp(row.url.replace(/^https?:\/\/[^/]+/, "").split("?")[0], 120);

// ---- model arithmetic ------------------------------------------------------------------------------------------
let model = null;

function decode(b64) {
    const s = atob(b64);
    const bytes = new Uint8Array(s.length);
    for (let i = 0; i < s.length; i++) bytes[i] = s.charCodeAt(i);
    return bytes.buffer;
}

/** IEEE 754 half (uint16 bits) → number. */
function half(bits) {
    const sign = bits & 0x8000 ? -1 : 1;
    const exp = (bits >> 10) & 0x1f;
    const frac = bits & 0x3ff;
    if (exp === 0) return sign * frac * 2 ** -24;
    if (exp === 31) return frac ? NaN : sign * Infinity;
    return sign * (1 + frac / 1024) * 2 ** (exp - 15);
}

function load() {
    if (model) return model;
    const buf = decode(BLOB);
    const dv = new DataView(buf);
    let o = 0;
    const u32 = () => {
        const v = dv.getUint32(o, true);
        o += 4;
        return v;
    };
    const align4 = () => {
        o += (4 - (o % 4)) % 4;
    };
    // Format 2 (export_js.py): varint gaps between sorted hashes, idf as an index into a small palette, coef float32.
    // Lossless: the same numbers as format 1, ~0.7 MB less in the gzip'd Worker bundle.
    const table = () => {
        const n = u32();
        const gapBytes = u32();
        const hash = new Uint32Array(n);
        let p = o;
        let h = 0;
        for (let i = 0; i < n; i++) {
            let v = 0;
            let shift = 0;
            let b;
            do {
                b = dv.getUint8(p++);
                v += (b & 127) * 2 ** shift;
                shift += 7;
            } while (b & 128);
            h += v;
            hash[i] = h;
        }
        o += gapBytes;
        align4();
        const k = u32();
        const palette = new Float32Array(buf, o, k);
        o += 4 * k;
        const idf = new Float32Array(n);
        for (let i = 0; i < n; i++) idf[i] = palette[dv.getUint16(o + 2 * i, true)];
        o += 2 * n;
        align4();
        let coef;
        if (INFO.coef16) {
            // export_js.py --coef16: float16, padded to 4 bytes
            coef = new Float32Array(n);
            for (let i = 0; i < n; i++) coef[i] = half(dv.getUint16(o + 2 * i, true));
            o += 2 * n;
            align4();
        } else {
            coef = new Float32Array(buf, o, n);
            o += 4 * n;
        }
        return { hash, idf, coef };
    };
    const ensemble = () => {
        const trees = u32();
        const nodes = u32();
        const e = { first: new Uint32Array(buf, o, trees) };
        o += 4 * trees;
        e.feature = new Uint8Array(buf, o, nodes);
        e.flags = new Uint8Array(buf, o + nodes, nodes);
        o += 2 * nodes;
        e.left = new Uint16Array(buf, o, nodes);
        e.right = new Uint16Array(buf, o + 2 * nodes, nodes);
        o += 4 * nodes;
        o += (8 - (o % 8)) % 8;
        e.value = new Float64Array(buf, o, nodes);
        o += 8 * nodes;
        return e;
    };
    model = { word: table(), char: table(), address: table() };
    model.withAddress = ensemble();
    model.noAddress = ensemble();
    return model;
}

function fnv(s) {
    let h = 0x811c9dc5;
    for (let i = 0; i < s.length; i++) {
        h ^= s.charCodeAt(i);
        h = Math.imul(h, 0x01000193);
    }
    return h >>> 0;
}

function find(hashes, h) {
    let lo = 0;
    let hi = hashes.length - 1;
    while (lo <= hi) {
        const mid = (lo + hi) >>> 1;
        const v = hashes[mid];
        if (v === h) return mid;
        if (v < h) lo = mid + 1;
        else hi = mid - 1;
    }
    return -1;
}

/** sum over the terms of l2-normalised (1 + ln tf) * idf, times the term's coefficient (one vectorizer's share of the dot product). */
function part(table, terms) {
    const counts = new Map();
    for (const t of terms) {
        const i = find(table.hash, fnv(t));
        if (i >= 0) counts.set(i, (counts.get(i) || 0) + 1);
    }
    let norm = 0;
    let dot = 0;
    for (const [i, c] of counts) {
        const w = (1 + Math.log(c)) * table.idf[i];
        norm += w * w;
        dot += w * table.coef[i];
    }
    return norm > 0 ? dot / Math.sqrt(norm) : 0;
}

const sigmoid = (z) => 1 / (1 + Math.exp(-z));

function predict(e, baseline, x) {
    let raw = baseline;
    for (let t = 0; t < e.first.length; t++) {
        const start = e.first[t];
        let n = start;
        while (!(e.flags[n] & 1)) {
            const v = x[e.feature[n]];
            const left = Number.isNaN(v) ? (e.flags[n] & 2) !== 0 : v <= e.value[n];
            n = start + (left ? e.left[n] : e.right[n]);
        }
        raw += e.value[n];
    }
    return sigmoid(raw);
}

const LOGGED = new Set(INFO.logged);

function sideFeatures(row, ruleIds, indonesian) {
    const f = INFO.feats.map((k) => {
        const v = Number(row.feats[k] ?? 0);
        return Math.fround(LOGGED.has(k) ? Math.log1p(v) : v);
    });
    const rules = INFO.rule_signals.map((s) => (ruleIds.includes(s) ? 1 : 0));
    return [...f, ...rules, indonesian ? 1 : 0];
}

/** Model scores for one row: { words, address, final } (final = mean of the two combiners, as in the lab). */
export function modelScores(row, ruleIds) {
    const m = load();
    const text = wordsText(row);
    const words = sigmoid(part(m.word, wordTerms(text)) + part(m.char, charWbTerms(text, 3, 5)) + INFO.words_intercept);
    const address = sigmoid(part(m.address, charTerms(addressText(row), 2, 4)) + INFO.address_intercept);
    const indonesian = isIndonesian(row);
    const side = sideFeatures(row, ruleIds, indonesian);
    const withAddress = predict(m.withAddress, INFO.baselines.with_address, [words, address, ...side]);
    const noAddress = predict(m.noAddress, INFO.baselines.no_address, [words, ...INFO.no_address_columns.map((i) => side[i])]);
    return { words, address, final: (withAddress + noAddress) / 2, indonesian };
}

// ---- claim gate v3g (lab eval_v3.py claim_g; chat links are not in the snapshot, so they never count here) --------------
const ASKS = new Set(["asks_otp", "asks_pin", "asks_ktp", "asks_cvv", "asks_card", "asks_selfie_ktp", "brand_logo_offsite"]);
const LURE = /\bklaim\b|pemenang|hadiah|undian|bansos|bantuan sosial|pencairan|pembatalan|call center|claim (your|now)|you have won|congratulations|verify your|account (is )?(locked|suspended)|unusual activity/i;
const CRED = new RegExp(
    "\\b(webmail|mailbox|e-?mail password|sign in to (your account|continue)|secured? login|login session|" +
        "shared (a |the )?(document|file)|view (the )?document|onedrive|sharepoint|office ?365|outlook|microsoft|docusign|" +
        "seed phrase|recovery phrase|metamask|" +
        "don.t recognize (you|your device)|incorrect (e-?mail|password)|account verification|update your (account|payment))\\b",
    "i",
);
const PASS_WORDS = 0.75;
const BUILDERS = ["weebly.com", "ubpages.com", "godaddysites.com", "wixsite.com", "jimdosite.com", "square.site", "mystrikingly.com",
    "sites.google.com", "webflow.io", "carrd.co", "site123.me", "yolasite.com"];
const PASS_LABEL = /password|passcode|kata (sandi|laluan)|mot de passe|contrase[nñ]a|senha|passwort|parola|wachtwoord|密码|密碼|пароль/iu;
const USER_LABEL = /e-?mail|user ?(name|id)|username|identifiant|usuario|utente|nome utente|login/i;
const ODD_PASS = /\bp(?!assword\b)[a@äαàá4][s$5ѕ][s$5ѕ*][wvｗ]{1,2}[o0οø*][r][d]\b|\bpassvvord\b|\bwebmai[I1]\b|\bpasswrd\b/iu;
const EXTRA_BRANDS = { roblox: "roblox.com", garena: "garena.com", "free fire": "garena.com", xfinity: "xfinity.com", pinterest: "pinterest.com" };
const under = (host, d) => host === d || host.endsWith("." + d);

/** True when the page makes a claim (brand, sensitive ask, lure, credential words ...). Without one, warn/block drop to gate. */
export function makesClaim(row, ruleIds, words) {
    const f = row.feats;
    const host = row.host.toLowerCase();
    const tx = row.title + " " + cp(row.text, 4000);
    const head = (row.title + " " + host).toLowerCase();
    const lure = LURE.test(tx);
    const form = Boolean(f.passwordField) || (f.forms >= 1 && f.fields >= 2);
    const brand = Boolean(f.brandsInTitle || f.brandInHost || f.brandOffsite) || (Boolean(f.brandsInText || f.brandTextOffsite) && (form || lure));
    const builder = BUILDERS.some((b) => under(host, b));
    return (
        brand ||
        lure ||
        ruleIds.some((id) => ASKS.has(id)) ||
        CRED.test(tx) ||
        (Boolean(f.passwordField) && words >= PASS_WORDS) ||
        ODD_PASS.test(tx) ||
        (builder && (PASS_LABEL.test(tx) || ODD_PASS.test(tx)) && USER_LABEL.test(tx)) ||
        Object.entries(EXTRA_BRANDS).some(([b, d]) => head.includes(b) && !under(host, d))
    );
}

// ---- tier ------------------------------------------------------------------------------------------------------
function tierFor(final, indonesian, official) {
    if (official) return "safe";
    const lim = INFO.thresholds[indonesian ? "indonesian" : "other"];
    return ["block", "warn", "gate"].find((t) => final >= lim[t]) ?? "safe";
}

/**
 * The model's answer for one sanitised snapshot.
 * @param {object} snapshot sanitised PageSnapshot
 * @param {{ ruleIds?: string[], ageDays?: number|null }} [ctx] ruleIds: layer 3 rule signal ids (before new_domain);
 *   ageDays: RDAP domain age, null when unknown
 * @returns {{ tier: "safe"|"gate"|"warn"|"block", final: number, words: number, address: number, claim: boolean, young: boolean }}
 *   gate is reported, but Shoo treats it as safe (no signal): decided 2026-11-17.
 */
export function scoreImpersonation(snapshot, { ruleIds = [], ageDays = null } = {}) {
    const row = pageRow(snapshot);
    const official = Boolean(row.feats.official) || isPopular(row.host) || OWNED.some((d) => under(row.host.toLowerCase(), d));
    const { words, address, final, indonesian } = modelScores(row, ruleIds);
    let tier = tierFor(final, indonesian, official);
    const flagged = tier === "warn" || tier === "block";
    const claim = flagged ? makesClaim(row, ruleIds, words) : false;
    if (flagged && !claim) tier = "gate";
    const young = !row.feats.sharedHost && !official && Number.isFinite(ageDays) && ageDays < YOUNG_DAYS;
    if (young && tier !== "warn" && tier !== "block") tier = "warn";
    const brandInHost = !official && brandHost(row);
    const lureInHost = !official && lureHost(row);
    if ((brandInHost || lureInHost) && tier !== "warn" && tier !== "block") tier = "warn";
    // Pretends to be a brand (brand in someone else's domain, or the brand's logo off its own site) AND asks for a login
    // (password field, or a password/OTP/PIN/card ask) = block. Lab eval_v3.py "lb": no legit page newly blocked; with
    // "brand in the title" as well it blocked trakteer.id, pajaknow.id, beritasatu.com ("Masuk dengan Google"), so not that.
    const pretends = brandInHost || ruleIds.includes("brand_logo_offsite");
    const asksLogin = Boolean(row.feats.passwordField) || ruleIds.some((id) => LOGIN_ASKS.has(id));
    const loginBlock = !official && pretends && asksLogin;
    if (loginBlock) tier = "block";
    return { tier, final, words, address, claim, young, brandHost: brandInHost, lureHost: lureInHost, loginBlock };
}

const LOGIN_ASKS = new Set(["asks_password", "asks_otp", "asks_pin", "asks_card", "asks_cvv"]);
// Brand-owned domains outside detector/data/brands.json (checked by Imelda 2026-11-18): never flagged by this model.
const OWNED = ["mandirikartukredit.com"];

// ---- lure word in the address (lab eval_v3.py host3+lure2, 2026-11-18) --------------------------------------------
// program-hadiah-pt-android.blogspot.com, undian-tselpoin-2015.blogspot.com: the name the scammer picked IS the lure.
// Indonesian words only: the English ones (prize, giveaway, reward, claim) caught 5 scams and made every false flag
// (nobelprize.org, giveawayoftheday.com). The page must also name a brand or use a lure word.
// Lab: fresh scam 76.3% → 87.6%, no extra false flag in any legit set (Kaggle 44/17,410, Indonesian calibration 14/805).
const HOST_LURE = /hadiah|undian|bansos|pemenang|klaim|pencairan|bantuan/;

/** Lure word in the part of the address the owner chose (subdomain on a shared host, else the domain label). */
export function lureHost(row) {
    const f = row.feats;
    const host = row.host.toLowerCase();
    if (RESTRICTED.test(host)) return false;
    const label = (f.sharedHost ? host : site(host)).split(".")[0];
    if (!HOST_LURE.test(label)) return false;
    return Boolean(f.brandsInTitle || f.brandsInText) || LURE.test(row.title + " " + cp(row.text, 4000));
}

// ---- brand in the address (lab eval_v3.py v3g+umur+host3, 2026-11-18) ----------------------------------------------
// appleid-icloudmac.com: brand in the host, brand on the page, model only 0.26 → gate. A brand name inside someone
// else's domain is the impersonation itself, so it is at least warn. Skipped: the brand's own domains under another
// TLD (google.org, registry.amazon: the domain label or the TLD IS the brand name) and restricted-registration
// domains (campus/government: bsi.ac.id). Lab: fresh scam 66.5% → 76.3%, Kaggle legit unchanged (44/17,410).
const BRAND_LABELS = new Set(BRAND_NAMES.flat().map((n) => n.replace(/\s+/g, "")));
const RESTRICTED = /\.(ac|sch|go|mil|desa)\.id$|\.(edu|gov|mil)$|\.(ac|edu|gov|go|mil)\.[a-z]{2}$/;

/** Brand name in the host of a domain the brand doesn't own, and the page names a brand too (title or text). */
export function brandHost(row) {
    const f = row.feats;
    if (!f.brandInHost || !(f.brandsInTitle || f.brandsInText)) return false;
    const host = row.host.toLowerCase();
    const labels = site(host).split(".");
    return !RESTRICTED.test(host) && !BRAND_LABELS.has(labels[0]) && !BRAND_LABELS.has(labels[labels.length - 1]);
}

/** Signal for a warn/block answer, null otherwise. No `evidence`: a model score is not text on the page. */
export function buildModelSignal(result) {
    if (!result || (result.tier !== "warn" && result.tier !== "block")) return null;
    return {
        id: MODEL_SIGNAL_ID,
        layer: 3,
        weight: MODEL_WEIGHTS[result.tier],
        label: { en: "Page looks like a fake copy of another site", id: "Halaman ini mirip tiruan situs lain" },
        labelSimple: { en: "Looks like a fake site", id: "Terlihat seperti situs palsu" },
    };
}
